tool_input.command:
cat >> test/invoices.test.js << 'EOFTEST'

test('lineVAT calculates VAT on amount after discount', () => {
  const line = { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 10, unitPrice: 9500, vatRate: 21, discountPercent: 0 };
  const result = lineVAT(line);
  assert.equal(result.ok, true);
  assert.equal(result.value, 19950);
});

test('lineVAT with discount', () => {
  const line = { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 10, unitPrice: 9500, vatRate: 21, discountPercent: 20 };
  const result = lineVAT(line);
  assert.equal(result.ok, true);
  assert.equal(result.value, 15960);
});

test('lineVAT with zero VAT rate', () => {
  const line = { sku: 'WORKSHOP-DAY', name: 'Workshop', qty: 1, unitPrice: 60000, vatRate: 0, discountPercent: 0 };
  const result = lineVAT(line);
  assert.equal(result.ok, true);
  assert.equal(result.value, 0);
});

test('invoiceTotals with VAT', () => {
  const result = createInvoice({ customerId: 'C-002', issueDate: '2025-02-15', lines: [{ sku: 'DEV-HOUR', qty: 10 }] });
  const totals = invoiceTotals(result.value);
  assert.equal(totals.value.subtotal, 95000);
  assert.equal(totals.value.discount, 0);
  assert.equal(totals.value.vat, 19950);
  assert.equal(totals.value.total, 114950);
});

test('invoiceTotals with VAT and discount', () => {
  const result = createInvoice({ customerId: 'C-002', issueDate: '2025-02-15', lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 20 }] });
  const totals = invoiceTotals(result.value);
  assert.equal(totals.value.subtotal, 95000);
  assert.equal(totals.value.discount, 19000);
  assert.equal(totals.value.vat, 15960);
  assert.equal(totals.value.total, 91960);
});

test('invoiceTotals with multiple VAT rates', () => {
  const result = createInvoice({ customerId: 'C-002', issueDate: '2025-02-15', lines: [{ sku: 'DEV-HOUR', qty: 10 }, { sku: 'PRINT-A4', qty: 100 }, { sku: 'WORKSHOP-DAY', qty: 1 }] });
  const totals = invoiceTotals(result.value);
  assert.equal(totals.value.subtotal, 158700);
  assert.equal(totals.value.vat, 20283);
  assert.equal(totals.value.total, 178983);
});

test('invoiceTotals formula is subtotal - discount + vat', () => {
  const result = createInvoice({ customerId: 'C-001', issueDate: '2025-02-15', lines: [{ sku: 'DEV-HOUR', qty: 10 }] });
  const totals = invoiceTotals(result.value);
  assert.equal(totals.value.total, totals.value.subtotal - totals.value.discount + totals.value.vat);
});
EOFTEST
